Here is the commit message:
crypto: af_alg - Fix page reassignment overflow in
 af_alg_pull_tsgl

When page reassignment was added to af_alg_pull_tsgl the original
loop wasn't updated so it may try to reassign one more page than
necessary.

Add the check to the reassignment so that this does not happen.

Also update the comment which still refers to the obsolete offset
argument.

Reported-by: syzbot+d23888375c2737c17ba5@syzkaller.appspotmail.com
Fixes: e870456d8e7c ("crypto: algif_skcipher - overhaul memory management")
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
In `af_alg_pull_tsgl`, when iterating scatterlist entries, the code checks only that `dst` is non-NULL before reassigning the page to the destination. However, it does not check whether the length (`plen`) of the current scatterlist segment is zero. This allows an extra page reassignment when `plen` is zero, causing a page reassignment overflow (one more page than necessary). The fix adds `plen` to the condition to prevent reassigning zero-length segments.

Here is the patch:
  */
 void af_alg_pull_tsgl(struct sock *sk, size_t used, struct scatterlist *dst)
 {
 	struct alg_sock *ask = alg_sk(sk);
 	struct af_alg_ctx *ctx = ask->private;
 	struct af_alg_tsgl *sgl;
 	struct scatterlist *sg;
 	unsigned int i, j = 0;

 	while (!list_empty(&ctx->tsgl_list)) {
 		sgl = list_first_entry(&ctx->tsgl_list, struct af_alg_tsgl,
 				       list);
 		sg = sgl->sg;

 		for (i = 0; i < sgl->cur; i++) {
 			size_t plen = min_t(size_t, used, sg[i].length);
 			struct page *page = sg_page(sg + i);

 			if (!page)
 				continue;

 			/*
 			 * Assumption: caller created af_alg_count_tsgl(len)
 			 * SG entries in dst.
 			 */
-			if (dst) {
-				/* reassign page to dst after offset */
+			if (dst && plen) {
+				/* reassign page to dst */
 				get_page(page);
 				sg_set_page(dst + j, page, plen, sg[i].offset);
 				j++;
 			}

 			sg[i].length -= plen;
 			sg[i].offset += plen;

 			used -= plen;
 			ctx->used -= plen;

 			if (sg[i].length)
 				return;

 			put_page(page);
 			sg_assign_page(sg + i, NULL);
 		}

 		list_del(&sgl->list);
 		sock_kfree_s(sk, sgl, struct_size(sgl, sg, MAX_SGL_ENTS + 1));
 	}

 	if (!ctx->used)
 		ctx->merge = 0;
 	ctx->init = ctx->more;
 }
 EXPORT_SYMBOL_GPL(af_alg_pull_tsgl);


